for r in c.execute("select * from determination_gates"): print(dict(r))
print("\n=== evidence_sources REF-01002 ===")
for r in c.execute("select * from evidence_sources where ref_id='REF-01002'"): print(dict(r))
print("\n=== tables mentioning REF-01002 (row counts) ===")
for (t,) in c.execute("select name from sqlite_master where type='table'"):
    cols=[x[1] for x in c.execute(f'pragma table_info("{t}")')]
    for col in cols:
        if col in ('ref_id','source_ref_id','governing_ref_id','anchor_ref_id','cited_ref_id','citing_ref_id'):
            n=c.execute(f'select count(*) from "{t}" where "{col}"=?',('REF-01002',)).fetchone()[0]
